@startuml

class Person {
  + personID : int
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : int
}

class ScientificArticle {
  + DOI : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class AuthorPosition {
  + position : int
}

Person "1" -- "0..*" ResearchInstitution : worksFor
Person "1" -- "0..*" ScientificArticle : author
Person "1" -- "0..*" PeerReviewedPaper : reviewer
ScientificArticle "1" *-- "1..*" AuthorPosition
AuthorPosition "1" -- "1" Person
PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

ResearchInstitution "1" -- "0..*" TechnicalReport : publishes
Publisher "1" -- "0..*" Journal : publishes
ResearchInstitution "0..*" -- "0..*" Journal : subscribes

PeerReviewedPaper "0..*" -- "0..*" Journal : publishedIn

@enduml

